import{_ as e}from"./chunks/hero.B72zu8Q2.js";import{_ as r,c as a,al as n,j as l,o as i}from"./chunks/framework.ByhWQ_D0.js";const p=JSON.parse('{"title":"Amovlab F410 Drone","description":"","frontmatter":{},"headers":[],"relativePath":"uk/complete_vehicles_mc/amov_F410_drone.md","filePath":"uk/complete_vehicles_mc/amov_F410_drone.md"}'),d={name:"uk/complete_vehicles_mc/amov_F410_drone.md"};function s(o,t,c,g,m,y){return i(),a("div",null,t[0]||(t[0]=[n('<h1 id="amovlab-f410-drone" tabindex="-1">Amovlab F410 Drone <a class="header-anchor" href="#amovlab-f410-drone" aria-label="Permalink to &quot;Amovlab F410 Drone&quot;">​</a></h1><p>The <a href="https://amovlab.com/product/detail?pid=32" target="_blank" rel="noreferrer">Amovlab F410</a> is a medium-small drone platform with a 410mm wheelbase, equipped with Pixhawk 6c open-source flight controller, M8N-GPS, brushless motors, customized hard-case battery, Minihomer data link, optical flow ranging module, camera and other devices. It can be used immediately after receiving, capable of meeting indoor/outdoor stable flight and teaching development requirements.</p><p><img src="'+e+'" alt="Amovlab f410 Hero Image"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The vehicle comes with everything needed to fly, including the battery and a remote control. It is pre-installed with PX4 v1.15.4 at time of writing (a more recent version may be used in future).</p></div><h2 id="загальнии-огляд" tabindex="-1">Загальний огляд <a class="header-anchor" href="#загальнии-огляд" aria-label="Permalink to &quot;Загальний огляд&quot;">​</a></h2><ol><li>Can serve as a basic flight platform, paired with Pixhawk 6C flight controller to achieve optical flow and GPS fusion positioning, enabling stable flight both indoors and outdoors. It is one of the most stable basic flight platforms on the market.</li><li>Sturdy and reliable structure, with key parts made of aluminium alloy and carbon fibre, high strength and not easily damaged.</li><li>High stability, providing industrial-grade stability assurance, friendly to beginners, offering simplified version of interactive PC to enhance flight experience, can be initially used for outdoor aerial photography and image collection.</li><li>Has rich open-source code support, and can be used with PX4, FMT, and ArduPilot.</li><li>Video can be streamed from the UAV webcam to QGroundControl.</li><li>The drone has a lot of room and support for expansion, including for adding on-board computers, range sensors, and other payloads. <ul><li>Compatibility with many different components, providing platform for loading other user sensors, preparing for functional model development.</li><li>Abundant power supply making it perfect for installing additional sensors and onboard computers (including 5 external output voltages, 3 channels of 5V, 2 channels of 12V).</li><li>Pc-SDK support. This is a PC-based Python SDK Library based on MAVSDK that significantly simplifies UAV development compared to other approaches, such as using ROS or using C++. All you need is a basic understanding of Python programming and some simple coordinate system principles!</li><li>The <a href="https://docs.amovlab.com/f450-v6c-wiki/#/en/" target="_blank" rel="noreferrer">documentation</a> shows many of the options.</li></ul></li><li>Quasi-smart battery. The battery has a hard housing design that makes easy to install and remove. It provides accurate power estimates, but does not have some more advanced &quot;smart battery&quot; features.</li></ol><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><ul><li><a href="https://amovlab.com/product/detail?pid=32" target="_blank" rel="noreferrer">Amovlab F410 Drone</a></li></ul><h2 id="документація" tabindex="-1">Документація <a class="header-anchor" href="#документація" aria-label="Permalink to &quot;Документація&quot;">​</a></h2><h3 id="характеристики" tabindex="-1">Характеристики <a class="header-anchor" href="#характеристики" aria-label="Permalink to &quot;Характеристики&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Специфікація</th><th style="text-align:center;">F410_V6C Flight Platform</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Aircraft</strong></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">Розміри</td><td style="text-align:center;">Length 290mm × Width 290mm × Height 240mm (Wheelbase 410mm)</td></tr><tr><td style="text-align:center;">Empty Weight</td><td style="text-align:center;">1056g</td></tr><tr><td style="text-align:center;">Max Takeoff Weight</td><td style="text-align:center;">2200g</td></tr><tr><td style="text-align:center;">Max Ascent Speed</td><td style="text-align:center;">1.5m/s</td></tr><tr><td style="text-align:center;">Max Descent Speed</td><td style="text-align:center;">0.7m/s</td></tr><tr><td style="text-align:center;">Max Horizontal Speed</td><td style="text-align:center;">10m/s</td></tr><tr><td style="text-align:center;">Max Hovering Time</td><td style="text-align:center;">21min</td></tr><tr><td style="text-align:center;">Max Tilt Angle</td><td style="text-align:center;">30°</td></tr><tr><td style="text-align:center;">Operating Temperature</td><td style="text-align:center;">6℃-40℃</td></tr><tr><td style="text-align:center;">Hovering Accuracy</td><td style="text-align:center;">M8N GPS Vertical ±0.5m M8N GPS Horizontal ±0.8m</td></tr><tr><td style="text-align:center;">Hovering Accuracy</td><td style="text-align:center;">RTK Vertical ±0.1m RTK Horizontal ±0.15m</td></tr><tr><td style="text-align:center;"><strong>Flight Control System</strong></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">Процесор</td><td style="text-align:center;">FMU: STM32H743; IO Processor: STM32F103</td></tr><tr><td style="text-align:center;">Accelerometer</td><td style="text-align:center;">BMI055/ICM-42688-P</td></tr><tr><td style="text-align:center;">Gyroscope</td><td style="text-align:center;">BMI055/ICM-42688-P</td></tr><tr><td style="text-align:center;">Магнітометр</td><td style="text-align:center;">IST8310</td></tr><tr><td style="text-align:center;">Барометр</td><td style="text-align:center;">MS5611</td></tr><tr><td style="text-align:center;">Вага</td><td style="text-align:center;">59.3g</td></tr><tr><td style="text-align:center;">Розміри</td><td style="text-align:center;">Length 84.8mm × Width 44mm × Height 12.4mm</td></tr><tr><td style="text-align:center;"><strong>Perception</strong></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">Optical Flow &amp; Rangefinder Module</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">Вага</td><td style="text-align:center;">5.0g</td></tr><tr><td style="text-align:center;">Розміри</td><td style="text-align:center;">Length 29mm × Width 16.5mm × Height 15mm</td></tr><tr><td style="text-align:center;">Range Measurement</td><td style="text-align:center;">0.01-8m</td></tr><tr><td style="text-align:center;">Ranging FOV</td><td style="text-align:center;">6°</td></tr><tr><td style="text-align:center;">Optical Flow FOV</td><td style="text-align:center;">42°</td></tr><tr><td style="text-align:center;">Споживання електроенергії</td><td style="text-align:center;">500mW</td></tr><tr><td style="text-align:center;">Operating Voltage</td><td style="text-align:center;">4.0-5.5V</td></tr><tr><td style="text-align:center;">Optical Flow Working Distance</td><td style="text-align:center;">&gt; 80mm</td></tr><tr><td style="text-align:center;">Output Interface</td><td style="text-align:center;">UART</td></tr><tr><td style="text-align:center;"><strong>Data Link</strong></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">Data Link Solution</td><td style="text-align:center;">MINI HOMER</td></tr><tr><td style="text-align:center;">Смуга частот</td><td style="text-align:center;">Sub 1G Band</td></tr><tr><td style="text-align:center;">Operating Voltage</td><td style="text-align:center;">12V</td></tr><tr><td style="text-align:center;">Max Effective Range</td><td style="text-align:center;">1200m</td></tr><tr><td style="text-align:center;"><strong>Camera</strong></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">Модель</td><td style="text-align:center;">IVG-G4</td></tr><tr><td style="text-align:center;">Video Processing</td><td style="text-align:center;">H.265+ Encoding, Dual Streams, AVI Format</td></tr><tr><td style="text-align:center;">Video Output</td><td style="text-align:center;">Main Stream: 2560×1440@18fps, 2304×1296@20fps；Sub Stream: 800×448@25fps</td></tr><tr><td style="text-align:center;">Operating Voltage</td><td style="text-align:center;">12V</td></tr><tr><td style="text-align:center;">Розміри</td><td style="text-align:center;">Length 38mm × Width 38mm</td></tr><tr><td style="text-align:center;"><strong>Battery</strong></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">Модель</td><td style="text-align:center;">FB45</td></tr><tr><td style="text-align:center;">Dimensions (L×W×H)</td><td style="text-align:center;">Length 130mm × Width 65mm × Height 40mm</td></tr><tr><td style="text-align:center;">Вага</td><td style="text-align:center;">470g</td></tr><tr><td style="text-align:center;">Charge Limit Voltage</td><td style="text-align:center;">16.8V</td></tr><tr><td style="text-align:center;">Nominal Voltage</td><td style="text-align:center;">14.8V</td></tr><tr><td style="text-align:center;">Rated Capacity</td><td style="text-align:center;">5000mAh</td></tr><tr><td style="text-align:center;">Rated Energy</td><td style="text-align:center;">74Wh</td></tr><tr><td style="text-align:center;">Налаштування</td><td style="text-align:center;">4s 1P</td></tr><tr><td style="text-align:center;"><strong>Charger</strong></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">Input Voltage</td><td style="text-align:center;">DC:9V-12V</td></tr><tr><td style="text-align:center;">Max Output Power</td><td style="text-align:center;">25W</td></tr><tr><td style="text-align:center;">Max Output Current</td><td style="text-align:center;">1500mA</td></tr><tr><td style="text-align:center;">Display Accuracy</td><td style="text-align:center;">±10mV</td></tr><tr><td style="text-align:center;">Розміри</td><td style="text-align:center;">Length 81mm × Width 50mm × Height 20mm</td></tr><tr><td style="text-align:center;">Вага</td><td style="text-align:center;">76g</td></tr><tr><td style="text-align:center;"><strong>Remote Controller</strong></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">Operating Voltage</td><td style="text-align:center;">4.5V-9V</td></tr><tr><td style="text-align:center;">Channels</td><td style="text-align:center;">8</td></tr><tr><td style="text-align:center;">Transmit Power</td><td style="text-align:center;">＜ 10mW</td></tr><tr><td style="text-align:center;">Вага</td><td style="text-align:center;">310g</td></tr><tr><td style="text-align:center;">Dimensions (L×W×H)</td><td style="text-align:center;">Length 179mm × Width 81mm × Height 161mm</td></tr></tbody></table><h2 id="посібники" tabindex="-1">Посібники <a class="header-anchor" href="#посібники" aria-label="Permalink to &quot;Посібники&quot;">​</a></h2><ul><li>Tutorials <a href="https://docs.amovlab.com/f450-v6c-wiki/#/en/" target="_blank" rel="noreferrer">English</a>/<a href="https://docs.amovlab.com/f450-v6c-wiki/#/" target="_blank" rel="noreferrer">Chinese</a> (docs.amovlab.com/)</li></ul><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h2><p>Amovlab previously supplied this vehicle with PX4 v1.13.</p><p>In order to upgrade to PX4 v1.15, you should select the <a href="./../config/airframe.html">X500 airframe</a> and import <a href="https://github.com/PX4/PX4-Autopilot/blob/main/docs/assets/airframes/multicopter/amovlab_f410/amovlabf410_drone_v1.15.4.params" target="_blank" rel="noreferrer">this parameter file</a> to apply the new <a href="./../config/actuators.html">actuator output configuration</a> (used from PX4 v1.14). Then retune as necessary.</p><p>Contact Amovlab for information about upgrading to other versions.</p><h2 id="відео" tabindex="-1">Відео <a class="header-anchor" href="#відео" aria-label="Permalink to &quot;Відео&quot;">​</a></h2>',18),l("lite-youtube",{videoid:"RzmI1d5093I",title:"F410 Mid-Axis UAVs"},null,-1)]))}const u=r(d,[["render",s]]);export{p as __pageData,u as default};
